// Board view. A second view at #/board that draws the repository's Issues as four columns. It
// reads them from one of two places and says on the page which one it used: site/board.json,
// the snapshot a workflow publishes beside this page, or, when a token has been connected in
// this browser, straight from the GitHub REST API. Nothing is written back either way, there is
// no drag and drop, and the board carries no state of its own: GitHub is the source of truth
// and the board is a picture of it.
//
// WHY THERE ARE TWO SOURCES. board.json is regenerated by an Action on every issue event and
// then published through Pages, so at its best it is a minute or two behind the change that
// caused it. Reading the API removes both waits and is what makes the board watchable while
// work moves. It costs a credential, so it is off unless one is already stored, and every
// refusal falls back to the snapshot rather than to a blank board.
//
// board.json is fetched same origin. The only other request this file can make is a GET to
// api.github.com, only when a token has been connected in this browser, carrying that token in
// an Authorization header, never in the URL and never into a file or a log.
(function () {
  'use strict';

  var SHAPE = 'expected {"generated": "...", "columns": [{"key": "...", "title": "...", ' +
              '"cards": [{"id": 1, "title": "...", "labels": [], "url": "..."}]}]}';

  var body = document.body;
  var nav = document.getElementById('navview');
  var meta = document.getElementById('bmeta');
  var host = document.getElementById('bbody');
  var statusEl = document.getElementById('bstatus');

  // How often each source is asked. The snapshot cannot change faster than the workflow that
  // writes it runs, so asking it oftener than every half minute only spends bandwidth. The API
  // is the fast path and is asked every ten seconds; an unchanged board answers 304 out of the
  // ETag below and GitHub does not count a 304 against the rate limit, so ordinary watching
  // costs one counted request per real change rather than six a minute.
  var SNAPSHOT_MS = 30000;
  var LIVE_MS = 10000;
  // Where the rate limit is treated as nearly spent, and how slowly the board polls once it is.
  // A fine-grained token is allowed five thousand requests an hour, which this is nowhere near;
  // the floor is here for the case where something else on the same token has spent it.
  var RATE_FLOOR = 100;
  var BACKOFF_MS = 120000;
  // Two pages of a hundred, matching the --limit 200 the generator asks gh for. Beyond that the
  // two sources would disagree, so they are wrong in the same place rather than in two places.
  var PER_PAGE = 100;
  var MAX_PAGES = 2;

  // ---- the column rule ---------------------------------------------------------------------
  // MIRRORED FROM scripts/sync_board.mjs, WHICH MUST CHANGE WITH THIS BLOCK. Everything from
  // here to buildColumns() reproduces that script's rules: the four columns and the label that
  // fills each, the default column for an unlabelled issue, a closed issue going to Done, a
  // NOT_PLANNED closure appearing in no column at all, Done drawn newest first and capped, and
  // the arithmetic that closed equals drawn plus hidden. The two copies cannot be one: that
  // script is not deployed, only site/ is, and this page loads classic scripts, so neither side
  // can import the other without a build step this repository does not have. If a rule here and
  // a rule there ever drift, the published board and the live board show different things about
  // the same issues, which is worse than either being wrong on its own.
  //
  // AND THE LABELS THEMSELVES ARE WRITTEN IN FOUR PLACES, NOT TWO, WHICH IS WHAT THIS PARAGRAPH
  // IS FOR. Issue 106. The sentence above named the pair that READS the vocabulary and was silent
  // about the two that do not, so a reader adding a fifth column, or renaming one, could sweep
  // everything this banner points at and still ship a label nothing sets and a document that
  // describes the old set:
  //
  //   site/board.js            here, the live board, reading the labels off the API
  //   scripts/sync_board.mjs   the generator, reading them off `gh issue list`
  //   scripts/set_status.sh    the only thing that WRITES them, and it rejects any other value
  //   KAIZEN.md                the prose that tells a contributor what the four are
  //
  // Nothing checks the four against each other, which is exactly why the list is written out
  // rather than described. A `status:` label that set_status.sh will not set is a column no card
  // can reach, and it fails silently: the issue simply stays in Raw.
  var COLUMNS = [
    { key: 'raw', title: 'Raw', label: 'status:raw' },
    { key: 'backlog', title: 'Backlog', label: 'status:backlog' },
    { key: 'in_progress', title: 'In progress', label: 'status:in-progress' },
    { key: 'done', title: 'Done', label: 'status:done' }
  ];
  var DEFAULT_COLUMN = 'raw';
  var DONE_VISIBLE = 8;
  var NOT_PLANNED = 'NOT_PLANNED';

  // `gh issue list --json stateReason` returns COMPLETED or NOT_PLANNED; the REST API's
  // state_reason field returns the same words lowercased, or null on an open issue. Both are
  // uppercased before the comparison, so one rule reads either.
  function columnFor(labels, state, stateReason) {
    if (String(state || '').toLowerCase() === 'closed') {
      if (String(stateReason || '').toUpperCase() === NOT_PLANNED) return null;
      return 'done';
    }
    for (var i = 0; i < COLUMNS.length; i++) {
      if (labels.indexOf(COLUMNS[i].label) !== -1) return COLUMNS[i].key;
    }
    return DEFAULT_COLUMN;
  }

  function toCard(iss) {
    var labels = (iss.labels || [])
      .map(function (l) { return typeof l === 'string' ? l : (l && l.name); })
      .filter(Boolean)
      .sort();
    return {
      id: iss.number,
      title: String(iss.title || '').trim(),
      labels: labels,
      // html_url, not url: the API's `url` is the API address of the issue, and the generator
      // asks gh for the field that is the page a reader opens.
      url: iss.html_url || '',
      closed: String(iss.state || '').toLowerCase() === 'closed',
      column: columnFor(labels, iss.state, iss.state_reason)
    };
  }

  function closedIssuesUrl(repo) {
    return 'https://github.com/' + repo + '/issues?q=is%3Aissue+is%3Aclosed';
  }

  function buildColumns(issues, repo) {
    var cards = issues.map(toCard).sort(function (a, b) { return a.id - b.id; });
    var closedTotal = cards.filter(function (c) { return c.closed; }).length;
    var notPlannedTotal = cards.filter(function (c) {
      return c.closed && c.column === null;
    }).length;
    return COLUMNS.map(function (col) {
      var own = cards.filter(function (c) { return c.column === col.key; });
      var ordered = col.key === 'done' ? own.slice().reverse() : own;
      var drawnCards = col.key === 'done' ? ordered.slice(0, DONE_VISIBLE) : ordered;
      var out = {
        key: col.key,
        title: col.title,
        cards: drawnCards.map(function (c) {
          return { id: c.id, title: c.title, labels: c.labels, url: c.url };
        })
      };
      if (col.key === 'done') {
        out.hidden = closedTotal - drawnCards.length;
        out.hiddenUrl = closedIssuesUrl(repo);
        // The same two assertions the generator makes, for the same reason: a count that does
        // not add up is a board claiming to be everything while hiding something. Here it
        // throws into the live path's catch, which leaves the last good board on screen and
        // marks it stale, rather than publishing arithmetic nobody checked.
        if (drawnCards.length + out.hidden !== closedTotal ||
            ordered.length + notPlannedTotal !== closedTotal) {
          throw new Error('done column does not account for every closed issue: drawn ' +
            drawnCards.length + ' + hidden ' + out.hidden + ' vs closed ' + closedTotal);
        }
      }
      return out;
    });
  }

  // ---- drawing -----------------------------------------------------------------------------
  function note(html) {
    var d = document.createElement('div');
    d.className = 'bnote';
    d.innerHTML = html;
    host.textContent = '';
    host.appendChild(d);
  }

  // The status label is what put the card in its column, so printing it on the card as well
  // says the same thing twice and gives the reader a second place to check it. The column
  // heading owns that fact; the chips carry only what the column does not already say.
  function shown(labels) {
    return labels.filter(function (l) { return String(l).indexOf('status:') !== 0; });
  }

  // Cards are ordered by issue number, ascending, which is the order they were filed in. It is
  // the only order the board holds that means anything: board.json carries no dates, and a
  // number never changes, so the same issues always land in the same places. Done is the one
  // exception and is drawn newest first, because a column of finished work is read at the end
  // that just moved.
  function byNumber(a, b) {
    var x = a && typeof a.id === 'number' ? a.id : Infinity;
    var y = b && typeof b.id === 'number' ? b.id : Infinity;
    return x - y;
  }

  function card(c) {
    var a = document.createElement(c && c.url ? 'a' : 'div');
    a.className = 'bcard';
    if (c && c.url) { a.href = c.url; a.target = '_blank'; a.rel = 'noopener noreferrer'; }

    var num = document.createElement('div');
    num.className = 'bnum';
    num.textContent = c && (c.id || c.id === 0) ? '#' + c.id : 'no number';
    a.appendChild(num);

    var t = document.createElement('p');
    t.className = 'btitle';
    t.textContent = (c && c.title) || 'untitled';
    a.appendChild(t);

    var labels = shown((c && Array.isArray(c.labels)) ? c.labels : []);
    if (labels.length) {
      var box = document.createElement('div');
      box.className = 'blabels';
      labels.forEach(function (l) {
        var s = document.createElement('span');
        s.className = 'chip';
        s.textContent = String(l);
        box.appendChild(s);
      });
      a.appendChild(box);
    }
    return a;
  }

  // An address out of board.json is only followed if it is an issues list on github.com, the
  // same rule the board link below obeys, so the page cannot be pointed somewhere else by an
  // edit to board.json. An address that fails the test costs the reader the link, not the line.
  function issuesHref(url) {
    return (typeof url === 'string' &&
      /^https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/issues(\?[\w%+=:.-]*)?$/.test(url)) ? url : null;
  }

  // The Done column is capped by the generator, and the generator also keeps issues closed as
  // not planned off the board altogether, so the cards the column holds are not all the closed
  // issues it stands for. The remainder is printed under them, as a line rather than a card,
  // because it names work that is off the board. It says "closed" and not "done": the count
  // covers duplicates and wontfixes as well as finished cards, and calling those done would be
  // the same false claim the column used to make by drawing them. An older board.json carries
  // neither field, and a board with nothing hidden carries a zero; both draw nothing.
  function more(col) {
    var n = col && typeof col.hidden === 'number' ? col.hidden : 0;
    if (!(n > 0)) return null;
    var href = issuesHref(col.hiddenUrl);
    var e = document.createElement(href ? 'a' : 'p');
    e.className = 'bmore';
    // The phrase carries no noun, so it is already right at one and needs no plural branch:
    // "and 1 more closed" and "and 16 more closed" both read.
    e.textContent = 'and ' + n + ' more closed';
    if (href) { e.href = href; e.target = '_blank'; e.rel = 'noopener noreferrer'; }
    return e;
  }

  function column(col) {
    var d = document.createElement('div');
    d.className = 'bcol';
    var h = document.createElement('h2');
    h.textContent = (col && (col.title || col.key)) || 'untitled column';
    var n = document.createElement('span');
    var cards = (col && Array.isArray(col.cards)) ? col.cards : [];
    n.textContent = cards.length;
    h.appendChild(n);
    d.appendChild(h);
    if (!cards.length) {
      // An empty column is a fact about the work, not a failure to load, so it keeps its
      // heading and its count and says plainly that it holds nothing.
      d.classList.add('bcol-empty');
      var e = document.createElement('p');
      e.className = 'bempty';
      e.textContent = 'no issues';
      d.appendChild(e);
    } else {
      // Done arrives newest first from the generator and stays in the order it arrives in; the
      // other columns are sorted here so a hand-edited board.json still draws in filing order.
      var list = col && col.key === 'done' ? cards.slice() : cards.slice().sort(byNumber);
      list.forEach(function (c) { d.appendChild(card(c)); });
    }
    var rest = more(col);
    if (rest) d.appendChild(rest);
    return d;
  }

  // The one link out of the board, back to the list it is a picture of. The address is taken
  // from a card rather than written here, and only if it is an issue URL on github.com, so the
  // page cannot be made to link somewhere else by editing board.json.
  function issuesUrl(data) {
    var found = null;
    data.columns.forEach(function (col) {
      ((col && col.cards) || []).forEach(function (c) {
        var m = c && typeof c.url === 'string' &&
          c.url.match(/^https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/issues\/\d+$/);
        if (m && !found) found = c.url.replace(/\/\d+$/, '');
      });
    });
    return found;
  }

  // ---- what is on screen, and what it cost to put there --------------------------------------
  // The board is now polled, so most answers are the answer that is already drawn. A poll that
  // rebuilt the same DOM would throw away the reader's scroll position and their focus, and
  // would make every card blink for no reason, so the payload is reduced to two signatures and
  // an answer that matches both writes nothing at all. The meta line and the columns are
  // signed separately because they go stale at different times: in live mode the columns can
  // stand still for an hour while the header line never changes either.
  var colsSig = null;
  var metaSig = null;
  var drawn = false;        // something real is on screen; a later failure must not clear it
  var source = '';          // 'live' or 'snapshot', whichever produced what is drawn
  var lastGood = 0;         // when the drawn board was last confirmed current
  var staleNote = '';       // why the most recent refresh failed, '' if it did not
  var fellBack = '';        // why live mode is off, '' if it is not
  var rateLow = false;      // the API rate limit is nearly spent and the board has slowed down

  function renderMeta(data) {
    var href = issuesUrl(data);
    var sig = (data.generated || '') + '|' + (href || '');
    if (sig === metaSig) return;
    metaSig = sig;
    meta.textContent = '';
    meta.appendChild(document.createTextNode(
      (data.generated ? 'Generated ' + data.generated + '. ' : '') + 'The board reflects '));
    if (href) {
      var a = document.createElement('a');
      a.href = href;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      a.textContent = 'GitHub Issues';
      meta.appendChild(a);
    } else {
      meta.appendChild(document.createTextNode('GitHub Issues'));
    }
    // #128 took the sentence after the link off, here and out of index.html's fallback copy of
    // it. A board with no control on any card and nothing that responds to a drag says both
    // halves of it by being that board.
    meta.appendChild(document.createTextNode('.'));
  }

  function renderColumns(data) {
    var sig = JSON.stringify(data.columns);
    if (sig === colsSig) return;
    colsSig = sig;
    var wrap = document.createElement('div');
    wrap.className = 'bcols';
    data.columns.forEach(function (c) { wrap.appendChild(column(c)); });
    host.textContent = '';
    host.appendChild(wrap);
  }

  function apply(data, src) {
    if (!data || !Array.isArray(data.columns)) {
      if (!drawn) {
        note('<b>board.json is present but not in the shape this view reads.</b><br>' + SHAPE);
      } else {
        stale('the answer was not in the shape this view reads');
      }
      return;
    }
    source = src;
    lastGood = Date.now();
    staleNote = '';
    renderMeta(data);
    renderColumns(data);
    drawn = true;
    paintStatus();
  }

  // A confirmation that nothing changed is as good as a fresh payload and is recorded the same
  // way: a 304 means the board on screen is current now, not that the refresh failed.
  function confirmed(src) {
    source = src;
    lastGood = Date.now();
    staleNote = '';
    paintStatus();
  }

  // A failed refresh never blanks a board that is already drawn. It keeps the last good one and
  // says in the status line that it is the last good one, because a board that quietly stops
  // updating looks exactly like a board where nothing is happening.
  function stale(reason) {
    staleNote = reason;
    paintStatus();
  }

  // ---- the status line -----------------------------------------------------------------------
  function ago(ms) {
    var s = Math.max(0, Math.round(ms / 1000));
    if (s < 60) return s + 's ago';
    var m = Math.round(s / 60);
    if (m < 60) return m + 'm ago';
    return Math.round(m / 60) + 'h ago';
  }

  // explainStatus is written for the filing popover, which has room for the whole hint. The
  // status line has one line, so it carries the first sentence and hangs the rest on the title
  // attribute. The hint itself is not rewritten here; see the note beside getShared().
  function firstSentence(text) {
    var cut = String(text).indexOf('. ');
    return cut > 0 ? String(text).slice(0, cut + 1) : String(text);
  }

  function statusText() {
    if (!lastGood && !fellBack) return '';
    var bits = [];
    if (lastGood) {
      bits.push((source === 'live' ? 'live from the GitHub API' : 'published snapshot') +
                ', updated ' + ago(Date.now() - lastGood));
    }
    if (staleNote) bits.push('last refresh failed (' + staleNote + '), showing the last good one');
    if (rateLow) bits.push('GitHub rate limit low, slowed to one check every two minutes');
    if (fellBack) bits.push('live mode off, ' + firstSentence(fellBack));
    return bits.join(' · ');
  }

  function paintStatus() {
    if (!statusEl) return;
    // Written only when it changes. The clock behind this ticks once a second and the age it
    // prints moves once a second for the first minute and then hardly at all, so almost every
    // tick writes nothing. It is deliberately not a spinner: a control that flashes on every
    // poll reports the polling rather than the board.
    var text = statusText();
    if (statusEl.textContent !== text) statusEl.textContent = text;
    var title = fellBack || '';
    if (title) {
      if (statusEl.getAttribute('title') !== title) statusEl.setAttribute('title', title);
    } else if (statusEl.hasAttribute('title')) {
      statusEl.removeAttribute('title');
    }
  }

  // ---- the two sources -----------------------------------------------------------------------
  // feedback.js publishes the repository name, the stored token and the explanation of GitHub's
  // refusals on window.ZMT, the way app.js publishes window.ZT. It is read here at call time and
  // never at load time, because index.html loads this file before that one. Reaching for its
  // explainStatus rather than writing a second copy is deliberate: the fact that GitHub answers
  // 404 rather than 403 for a private repository a token cannot reach is the one thing about
  // this API a reader cannot guess, and two copies of that sentence is one copy that goes stale.
  function getShared() {
    var g = window.ZMT;
    return (g && typeof g.token === 'function' && g.repo) ? g : null;
  }

  function explain(status, message) {
    var g = getShared();
    if (g && typeof g.explainStatus === 'function') return g.explainStatus(status, message);
    return 'GitHub API ' + status + (message ? ': ' + message : '');
  }

  var timer = null;         // the poll
  var ticker = null;        // the once-a-second clock under the status line
  var onBoard = false;
  var inFlight = false;
  var started = false;
  var liveEtag = '';
  // The token that was refused, held so that a different one connected afterwards is tried
  // again rather than being written off by the first one's failure. Compared, never printed,
  // and never sent anywhere but api.github.com.
  var refusedFor = '';
  // Set by a path that wants the next poll now rather than in an interval's time. It goes
  // through the scheduler instead of calling tick() directly, because a second fetch started
  // from inside the first one's handler runs while inFlight is still set and gets in its own
  // way; going round the loop once keeps one request in the air at a time.
  var pollSoon = false;

  function period() {
    if (pollSoon) return 0;
    if (rateLow) return BACKOFF_MS;
    return (source === 'live' && !fellBack) ? LIVE_MS : SNAPSHOT_MS;
  }

  function schedule() {
    clearTimeout(timer);
    timer = null;
    if (!onBoard || document.hidden) { pollSoon = false; return; }
    var wait = period();
    pollSoon = false;
    timer = setTimeout(tick, wait);
  }

  function done() {
    inFlight = false;
    schedule();
  }

  // Ask now rather than an interval from now, but through the scheduler rather than by calling
  // tick() from here, so that only one request is ever in the air.
  //
  // While the document is still parsing the first ask waits for DOMContentLoaded, and a zero
  // delay timer is not a substitute for that. index.html loads this file before feedback.js,
  // which is where window.ZMT comes from, and the parser yields between script tags: a timer
  // set from here fires in that gap, sees no token, and draws the published snapshot for a
  // reader who had connected one, who then waits a whole snapshot interval for the live board.
  // Both were measured, the second after the timer was tried as the fix for the first.
  function soon() {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', soon, { once: true });
      return;
    }
    pollSoon = true;
    schedule();
  }

  function tick() {
    if (!onBoard || document.hidden) return;
    // One request at a time. A slow answer must not let the next tick stack a second one behind
    // it, which on a bad connection is how a ten second poll becomes a queue.
    if (inFlight) return;
    var g = getShared();
    var token = g ? g.token() : '';
    if (token && token !== refusedFor) {
      if (fellBack) { fellBack = ''; liveEtag = ''; }   // a new token gets its own chance
      fetchLive(g.repo, token);
    } else {
      fetchSnapshot();
    }
  }

  function fetchSnapshot() {
    inFlight = true;
    fetch('board.json', { cache: 'no-store' }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.text();
    }).then(function (text) {
      var data;
      try {
        data = JSON.parse(text);
      } catch (err) {
        if (!drawn) note('<b>board.json could not be read as JSON.</b><br>' + SHAPE);
        else stale('board.json could not be read as JSON');
        return;
      }
      apply(data, 'snapshot');
    }).catch(function (err) {
      var why = String((err && err.message) || err);
      if (!drawn) {
        note('<b>No board yet.</b><br>This view reads <code>board.json</code>, which is ' +
             'generated from GitHub Issues and published beside this page. It is not there ' +
             'yet (' + why + '). File an issue with the feedback ' +
             'button and it will appear here once the board has been generated.');
      } else {
        stale(why);
      }
    }).then(done, done);
  }

  function apiUrl(repo) {
    // Sorted by when each issue was last touched, newest first, so that any change to any issue
    // lands on the first page. That is what makes the first page's ETag a sound test of whether
    // the board has moved even on a repository with more issues than one page holds. The order
    // the API answers in never reaches the drawing: buildColumns sorts by number.
    return 'https://api.github.com/repos/' + repo + '/issues?state=all&per_page=' + PER_PAGE +
           '&sort=updated&direction=desc';
  }

  function ghHeaders(token, etag) {
    var h = {
      'Authorization': 'Bearer ' + token,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28'
    };
    if (etag) h['If-None-Match'] = etag;
    return h;
  }

  // rel="next" out of the Link header, followed only if it is an address on api.github.com, the
  // same suspicion the board applies to every other address that arrives over the network.
  function nextLink(header) {
    var m = String(header || '').match(/<([^>]+)>;\s*rel="next"/);
    var url = m ? m[1] : '';
    return /^https:\/\/api\.github\.com\/[\w./-]+\?[\w%&=+.:-]*$/.test(url) ? url : '';
  }

  function readRate(res) {
    var left = parseInt(res.headers.get('x-ratelimit-remaining'), 10);
    if (!isNaN(left)) rateLow = left <= RATE_FLOOR;
    return isNaN(left) ? null : left;
  }

  function fetchLive(repo, token) {
    inFlight = true;
    var etag = '';
    var issues = [];
    var pages = 0;

    // The first page is asked conditionally and every further page unconditionally: only the
    // first one's ETag is kept, because it is the one that answers "has anything moved".
    var step = function (url, first) {
      return fetch(url, {
        cache: 'no-store',
        headers: ghHeaders(token, first ? liveEtag : '')
      }).then(function (res) {
        readRate(res);
        if (res.status === 304) return { unchanged: true };
        if (!res.ok) {
          return res.json().catch(function () { return null; }).then(function (j) {
            return { refused: res, message: (j && j.message) || '' };
          });
        }
        if (first) etag = res.headers.get('etag') || '';
        var link = res.headers.get('link');
        return res.json().then(function (got) {
          // Assert the shape rather than coercing it, for the reason the generator gives: a
          // defensive fallback to an empty list once turned a whole run into a confident
          // report of nothing.
          if (!Array.isArray(got)) {
            throw new Error('the API returned ' + typeof got + ' where an array was expected');
          }
          // The issues endpoint answers with pull requests in the list as well; the generator
          // asks gh, which does not. A pull request carries a pull_request object and an issue
          // does not, which is the only way the two are told apart here.
          issues = issues.concat(got.filter(function (i) { return i && !i.pull_request; }));
          pages += 1;
          var next = pages < MAX_PAGES ? nextLink(link) : '';
          return next ? step(next, false) : { ok: true };
        });
      });
    };

    step(apiUrl(repo), true).then(function (outcome) {
      if (outcome.unchanged) { confirmed('live'); return; }
      if (outcome.refused) { refused(outcome.refused, outcome.message); return; }
      liveEtag = etag;
      apply({ generated: '', columns: buildColumns(issues, repo) }, 'live');
    }).catch(function (err) {
      // A network error, or arithmetic that did not add up. Live mode stays on and the board
      // keeps the last good picture: this is a failed refresh, not a refusal.
      stale(String((err && err.message) || err));
    }).then(done, done);
  }

  function refused(res, message) {
    // A 403 or 429 with the rate limit spent is not a refusal of the token, it is a request to
    // come back later, so the board slows down instead of turning live mode off.
    if ((res.status === 403 || res.status === 429) && rateLow) {
      stale('GitHub API ' + res.status + ', rate limited');
      return;
    }
    fellBack = explain(res.status, message);
    refusedFor = currentToken();
    liveEtag = '';
    // The snapshot is asked for on the next turn of the loop rather than a poll interval later,
    // so a reader who arrives with a token this repository will not accept sees a board rather
    // than nothing while they work out why.
    pollSoon = true;
    paintStatus();
  }

  function currentToken() {
    var g = getShared();
    return g ? g.token() : '';
  }

  // ---- the view comes and goes ---------------------------------------------------------------
  function startClock() {
    if (ticker) return;
    ticker = setInterval(paintStatus, 1000);
  }

  function stopPolling() {
    clearTimeout(timer);
    timer = null;
    clearInterval(ticker);
    ticker = null;
  }

  function start() {
    if (!started) {
      started = true;
      note('Loading the board.');
    }
    startClock();
    paintStatus();
    soon();
  }

  // Polling stops dead while the tab is hidden: a board nobody is looking at does not need to
  // be current, and a background tab quietly spending a rate limit is the kind of cost that is
  // only noticed when something else runs out of it. Coming back asks immediately rather than
  // waiting out the interval, because the first thing a returning reader does is read the board.
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) {
      stopPolling();
    } else if (onBoard) {
      startClock();
      soon();
    }
  });

  function route() {
    onBoard = location.hash === '#/board';
    body.classList.toggle('board', onBoard);
    if (nav) {
      nav.textContent = onBoard ? 'diagram' : 'board';
      nav.setAttribute('href', onBoard ? '#/' : '#/board');
    }
    // The diagram is the other half of this page and does not show the board, so nothing is
    // polled while it is on screen. Coming back asks at once, for the same reason returning to
    // the tab does.
    if (onBoard) start(); else stopPolling();
  }

  window.addEventListener('hashchange', route);
  route();
})();
